head.script:
scwin.onpageload = function() {
    xmlDoc = WebSquare.ModelUtil.findInstanceNode("temp/vector")
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    alert(grid1.getUpdateDate());
};
scwin.trigger2_onclick = function(e) {
    grid1.removeRow(1);
};
scwin.trigger3_onclick = function(e) {
    grid1.setXML(WebSquare.ModelUtil.findInstanceNode("temp/vector"));
};
scwin.trigger4_onclick = function(e) {
    var tem_string = WebSquare.json.JSON2XMLString(grid1.getRemovedJSON());
    localStorage.setItem('removedJson', tem_string.indexOf("object"));
    //alert(WebSquare.json.JSON2XMLString(grid1.getRemovedJSON()));
};
scwin.trigger5_onclick = function(e) {
    grid1.removeRow(2);
};
scwin.checkVal = function() {
    return localStorage.getItem('removedJson') == "-1";
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    WebSquare.uiplugin.grid.prototype.getUpdateDate = function(status) {
        status = (status || "all").toLowerCase();
        window.colsep = this.getAttribute("colsep") || "^";
        window.rowsep = this.getAttribute("rowsep") || "|";
        window.mdata = this.getModifyedArray();
        window.colInfo = mdata.columnInfo();
        window.data = mdata.data;
        window.sendStr = "m" + colsep + "rownum";
        for (var col in colInfo) {
            sendStr += (colsep + colInfo[col])
        }
        sendStr += rowsep;
        window.midxs = this.getModifiedIndex();
        window.statstr = [];
        statstr["U"] = "u";
        statstr["D"] = "d";
        statstr["C"] = "i";
        window.removes = this.getRemovedJSON();
        if (removes != null && removes.length > 0) {
            for (var i = 0; i < removes.lenght; i++) {
                window.datastr = "d" + colsep + "-1";
                for (var j = 0; j < colInfo.length; j++) {
                    datastr += (colsep + removes[i][colInfo[j]]);
                }
                datastr += rowsep;
                sendStr += datastr;
            }
        }
        if (midxs != null) {
            var rowstatus;
            for (var i = 0; i < mdixs.length; i++) {
                rowstatus = this.getRowStatus(midxs[i]);
                window.datastr = statstr[rowstatus] + colsep + midxs[i];
                for (var j = (i * colInfo.length); j < ((i + 1) * colInfo.length); j++) {
                    datastr += (colsep + data[j]);
                }
                datastr += rowsep;
                if (status == "all" || (status == "insert" && rowstatus == "C") ||
                    (status == "update" && rowstatus == "U") ||
                    (status == "delete" && rowstatus == "D")) {
                    sendStr += datstr;
                }
            }
        }
        return sendStr;
    };
    var xmlDoc;
    localStorage.removeItem('removedJson');
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
